import { Controller, Put, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 결재가 진행되기 전 상태(기안·반려·회수)에서만 작성자가 수정할 수 있다.
const EDITABLE_STATUSES = ['기안', '반려', '회수'];

function isText(value: unknown): value is string {
  return typeof value === 'string' && value.trim().length > 0;
}

function isNumeric(value: unknown): boolean {
  if (typeof value === 'number') {
    return Number.isFinite(value);
  }
  if (typeof value === 'string') {
    return value.trim() !== '' && Number.isFinite(Number(value));
  }
  return false;
}

function invalid(message: string): ApiError {
  return new ApiError(422, 'PURCHASE_REQUEST_INVALID_INPUT', message);
}

@Controller('api/v1')
export class FnSfr02401Controller {
  @Put('/purchase-requests/:purchaseRequestId')
  async updatePurchaseRequest(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const data = checks.inputOf(req.body);
    const idText = req.params['purchaseRequestId'];
    if (!/^[0-9]+$/.test(idText)) {
      throw new ApiError(404, 'PURCHASE_REQUEST_NOT_FOUND', '구매품의서를 찾을 수 없습니다.');
    }
    const missing: string[] = [];
    if (!isNumeric(data['projectId'])) {
      missing.push('프로젝트');
    }
    if (!isNumeric(data['budgetItemId'])) {
      missing.push('예산과목');
    }
    if (!isText(data['title'])) {
      missing.push('품의 제목');
    }
    if (!isText(data['purchaseContent'])) {
      missing.push('구매 내용');
    }
    if (!isNumeric(data['amount'])) {
      missing.push('품의 금액');
    }
    if (missing.length > 0) {
      throw invalid('필수 입력값이 누락되었습니다: ' + missing.join(', '));
    }
    if (String(data['title']).length > 200) {
      throw invalid('품의 제목은 200자 이내로 입력하세요.');
    }
    if (Number(data['amount']) <= 0) {
      throw invalid('품의 금액은 0보다 커야 합니다.');
    }
    return transaction(async (db) => {
      const found = await db.query(
        'SELECT approval_status AS "approvalStatus" FROM purchase_request WHERE purchase_request_id = CAST(:id AS bigint) FOR UPDATE',
        { id: idText },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'PURCHASE_REQUEST_NOT_FOUND', '구매품의서를 찾을 수 없습니다.');
      }
      if (!EDITABLE_STATUSES.includes(found[0]['approvalStatus'])) {
        throw new ApiError(409, 'PURCHASE_REQUEST_NOT_EDITABLE', '결재 진행 중이거나 완료되어 수정할 수 없습니다.');
      }
      const project = await db.query(
        'SELECT project_id FROM project WHERE project_id = CAST(:projectId AS bigint)',
        { projectId: String(data['projectId']) },
      );
      if (project.length === 0) {
        throw invalid('선택한 프로젝트가 없습니다.');
      }
      const item = await db.query(
        'SELECT budget_item_id FROM budget_item WHERE budget_item_id = CAST(:budgetItemId AS bigint)',
        { budgetItemId: String(data['budgetItemId']) },
      );
      if (item.length === 0) {
        throw invalid('선택한 예산과목이 없습니다.');
      }
      const rows = await db.query(
        'UPDATE purchase_request SET project_id = CAST(:projectId AS bigint), budget_item_id = CAST(:budgetItemId AS bigint), title = :title, purchase_content = :purchaseContent, amount = CAST(:amount AS numeric), updated_at = now() WHERE purchase_request_id = CAST(:id AS bigint) RETURNING purchase_request_id AS "purchaseRequestId", approval_status AS "approvalStatus"',
        {
          id: idText,
          projectId: String(data['projectId']),
          budgetItemId: String(data['budgetItemId']),
          title: String(data['title']).trim(),
          purchaseContent: String(data['purchaseContent']),
          amount: String(data['amount']),
        },
      );
      return rows[0];
    });
  }
}

