import { useState } from 'react';
import {
  Badge,
  Band,
  DataTable,
  Drawer,
  Field,
  Form,
  LookupSelect,
  Num,
  NumberInput,
  Pairs,
  RefName,
  Select,
  TextInput,
  Tiles,
  call,
} from '../kit';
import type { PageProps, Row } from '../kit';

// 가정: 결재 진행 전 상태에서만 수정할 수 있다.
const EDITABLE = ['기안', '반려', '회수'];

export default function FnSfr02401Page({ role, notify }: PageProps) {
  // 조회 API가 없어 이 화면에서 처리한 결과를 목록으로 보인다.
  const [rows, setRows] = useState<Row[]>([]);
  const [creating, setCreating] = useState(false);
  const [editing, setEditing] = useState<Row | null>(null);
  const [detail, setDetail] = useState<Row | null>(null);
  const [cTitle, setCTitle] = useState('');
  const [cType, setCType] = useState('');
  const [cProject, setCProject] = useState<number | string>('');
  const [cItem, setCItem] = useState<number | string>('');
  const [cAmount, setCAmount] = useState<number | string>('');
  const [cReason, setCReason] = useState('');
  const [cInspection, setCInspection] = useState('false');
  const [eTitle, setETitle] = useState('');
  const [eProject, setEProject] = useState<number | string>('');
  const [eItem, setEItem] = useState<number | string>('');
  const [eAmount, setEAmount] = useState<number | string>('');
  const [eContent, setEContent] = useState('');

  function patchRow(id: unknown, values: Row) {
    setRows((old) => old.map((r) => (r.purchaseRequestId === id ? { ...r, ...values } : r)));
  }

  function openCreate() {
    setCTitle('');
    setCType('');
    setCProject('');
    setCItem('');
    setCAmount('');
    setCReason('');
    setCInspection('false');
    setCreating(true);
  }

  function openEdit(row: Row) {
    setETitle(String(row.title ?? ''));
    setEProject(row.projectId as number);
    setEItem(row.budgetItemId as number);
    setEAmount(row.amount as number);
    setEContent(String(row.purchaseContent ?? ''));
    setEditing(row);
  }

  async function create() {
    if (!cTitle.trim() || !cType || cProject === '' || cItem === '' || cAmount === '' || !cReason.trim()) {
      throw new Error('필수 입력값이 누락되었습니다. 품의 제목, 품의 유형, 프로젝트, 예산과목, 품의 금액, 품의 사유를 입력하세요.');
    }
    const res = await call('POST', '/purchase-requests', role, {
      title: cTitle.trim(),
      requestType: cType,
      projectId: cProject,
      budgetItemId: cItem,
      amount: cAmount,
      reason: cReason,
      assetInspectionRequired: cInspection === 'true',
    });
    setRows((old) => [
      {
        purchaseRequestId: res.purchaseRequestId,
        documentNo: res.documentNo,
        approvalStatus: res.approvalStatus,
        title: cTitle.trim(),
        requestType: cType,
        projectId: cProject,
        budgetItemId: cItem,
        amount: cAmount,
        reason: cReason,
        purchaseContent: '',
      },
      ...old,
    ]);
    setCreating(false);
    notify('구매품의서를 등록했습니다.');
  }

  async function update() {
    if (!editing) {
      return;
    }
    if (!eTitle.trim() || eProject === '' || eItem === '' || eAmount === '' || !eContent.trim()) {
      throw new Error('필수 입력값이 누락되었습니다. 프로젝트, 예산과목, 품의 제목, 구매 내용, 품의 금액을 입력하세요.');
    }
    const id = editing.purchaseRequestId;
    const res = await call('PUT', `/purchase-requests/${id}`, role, {
      projectId: eProject,
      budgetItemId: eItem,
      title: eTitle.trim(),
      purchaseContent: eContent,
      amount: eAmount,
    });
    patchRow(id, {
      projectId: eProject,
      budgetItemId: eItem,
      title: eTitle.trim(),
      purchaseContent: eContent,
      amount: eAmount,
      approvalStatus: res.approvalStatus,
    });
    setEditing(null);
    notify('구매품의서를 수정했습니다.');
  }

  async function submit(row: Row) {
    try {
      const res = await call('POST', `/purchase-requests/${row.purchaseRequestId}/submit`, role, {});
      patchRow(row.purchaseRequestId, { approvalStatus: res.approvalStatus });
      notify('상신했습니다.');
    } catch (e) {
      notify(e instanceof Error ? e.message : '상신하지 못했습니다.');
    }
  }

  const waiting = rows.filter((r) => r.approvalStatus === '기안').length;

  return (
    <div className="bento">
      <section className="box span-4">
        <h2>처리한 품의</h2>
        <Tiles items={[['건수', rows.length]]} />
      </section>
      <section className="box span-4">
        <h2>상신 대기</h2>
        <Tiles items={[['기안 건수', waiting]]} />
      </section>
      <section className="box span-4">
        <h2>품의 금액 합계</h2>
        <Tiles items={[['합계', <Num value={rows.reduce((s, r) => s + Number(r.amount || 0), 0)} />]]} />
      </section>
      <section className="box span-12">
        <h2>구매품의서</h2>
        <Band total={rows.length}>
          <button type="button" onClick={openCreate}>품의서 작성</button>
        </Band>
        <DataTable
          rows={rows}
          empty="이 화면에서 처리한 품의서가 없습니다."
          onRowClick={(row) => setDetail(row)}
          columns={[
            { key: 'documentNo', label: '문서번호' },
            { key: 'title', label: '품의 제목' },
            { key: 'projectId', label: '프로젝트', render: (r) => <RefName table="project" role={role} value={r.projectId} /> },
            { key: 'budgetItemId', label: '예산과목', render: (r) => <RefName table="budget_item" role={role} value={r.budgetItemId} /> },
            { key: 'amount', label: '품의 금액', render: (r) => <Num value={r.amount} /> },
            { key: 'approvalStatus', label: '결재 상태', render: (r) => <Badge value={r.approvalStatus} /> },
            {
              key: 'actions',
              label: '처리',
              render: (r) => (
                <span onClick={(e) => e.stopPropagation()}>
                  {EDITABLE.includes(String(r.approvalStatus)) && (
                    <button type="button" onClick={() => openEdit(r)}>수정</button>
                  )}
                  {r.approvalStatus === '기안' && (
                    <button type="button" onClick={() => submit(r)}>상신</button>
                  )}
                </span>
              ),
            },
          ]}
        />
      </section>
      {creating && (
        <Drawer title="구매품의서 작성" onClose={() => setCreating(false)}>
          <Form onSubmit={create} submit="등록">
            <Field label="품의 제목" required wide>
              <TextInput value={cTitle} onChange={setCTitle} />
            </Field>
            <Field label="품의 유형" required>
              <Select value={cType} onChange={setCType} options={[['지출', '지출'], ['구매', '구매']]} />
            </Field>
            <Field label="프로젝트" required>
              <LookupSelect table="project" role={role} value={cProject} onChange={setCProject} />
            </Field>
            <Field label="예산과목" required>
              <LookupSelect table="budget_item" role={role} value={cItem} onChange={setCItem} />
            </Field>
            <Field label="품의 금액" required>
              <NumberInput value={cAmount} onChange={setCAmount} />
            </Field>
            <Field label="품의 사유" required wide>
              <TextInput value={cReason} onChange={setCReason} multiline />
            </Field>
            <Field label="자산 검수 여부">
              <Select value={cInspection} onChange={setCInspection} options={[['false', '아니오'], ['true', '예']]} placeholder="선택" />
            </Field>
          </Form>
        </Drawer>
      )}
      {editing && (
        <Drawer title="구매품의서 수정" onClose={() => setEditing(null)}>
          <Form onSubmit={update} submit="저장">
            <Field label="프로젝트" required>
              <LookupSelect table="project" role={role} value={eProject} onChange={setEProject} />
            </Field>
            <Field label="예산과목" required>
              <LookupSelect table="budget_item" role={role} value={eItem} onChange={setEItem} />
            </Field>
            <Field label="품의 제목" required wide>
              <TextInput value={eTitle} onChange={setETitle} />
            </Field>
            <Field label="구매 내용" required wide>
              <TextInput value={eContent} onChange={setEContent} multiline />
            </Field>
            <Field label="품의 금액" required>
              <NumberInput value={eAmount} onChange={setEAmount} />
            </Field>
          </Form>
        </Drawer>
      )}
      {detail && (
        <Drawer title="구매품의서 상세" onClose={() => setDetail(null)}>
          <Pairs
            items={[
              ['문서번호', String(detail.documentNo ?? '')],
              ['품의 제목', String(detail.title ?? '')],
              ['프로젝트', <RefName table="project" role={role} value={detail.projectId} />],
              ['예산과목', <RefName table="budget_item" role={role} value={detail.budgetItemId} />],
              ['품의 금액', <Num value={detail.amount} />],
              ['구매 내용', String(detail.purchaseContent ?? '')],
              ['결재 상태', <Badge value={detail.approvalStatus} />],
            ]}
          />
        </Drawer>
      )}
    </div>
  );
}
